 @Test public void f5CU06BajaTemporalFormal(){ContextoEvaluacionCurricularV2DTO z=b();z.setBajaTemporalRegistrada(Boolean.TRUE);z.setReincorporacionRegistrada(Boolean.TRUE);assertTrue(t(x(z),CodigoSupuestoAvanceCondicionadoV2.BAJA_TEMPORAL));}
