 private EvaluacionCargaAcademicaV2DTO x(ContextoEvaluacionCurricularV2DTO z){return s.evaluarSombra(z).getEvaluacionCargaAcademica();} private boolean t(EvaluacionCargaAcademicaV2DTO q,CodigoSupuestoAvanceCondicionadoV2 c){return n(q,c)>0;} private int n(EvaluacionCargaAcademicaV2DTO q,CodigoSupuestoAvanceCondicionadoV2 c){int n=0;for(SupuestoAvanceCondicionadoV2DTO v:q.getSupuestosAvanceTipificados())if(v.getCodigo()==c)n++;return n;}
 private ContextoEvaluacionCurricularV2DTO b(){ContextoEvaluacionCurricularV2DTO z=new ContextoEvaluacionCurricularV2DTO();z.setIdPlan(1L);z.setPeriodoNormativo("2027-1");z.setSemestreObjetivo(5);z.setVersionReglas("PE2027-V1");z.setFechaEvaluacion(new Date(0));z.setActividadAcademicaComprobada(Boolean.TRUE);z.setPermanenciaDentroLimiteComprobada(Boolean.TRUE);z.setSeriacionComprobada(Boolean.TRUE);z.setEstructuraProgramaEducativoComprobada(Boolean.TRUE);z.setSancionImpedimentoConocida(Boolean.TRUE);z.setSancionImpedimentoRegistrada(Boolean.FALSE);z.getUnidades().add(r(1,1));z.getUnidades().add(u(50,5,EstadoUnidadCurricularV2.NO_CURSADA,CausaPendienteUnidadV2.NO_CURSAMIENTO));return z;} private ContextoEvaluacionCurricularV2DTO baja(){ContextoEvaluacionCurricularV2DTO z=b();UnidadEvaluacionCurricularV2DTO u=z.getUnidades().get(0);u.setEstado(EstadoUnidadCurricularV2.BAJA_PARCIAL);u.setCausa(CausaPendienteUnidadV2.BAJA_PARCIAL);u.setReprobacionVigenteConocida(Boolean.FALSE);return z;}
 private UnidadEvaluacionCurricularV2DTO r(long id,int sem){UnidadEvaluacionCurricularV2DTO u=u(id,sem,EstadoUnidadCurricularV2.REPROBADA,CausaPendienteUnidadV2.REPROBACION);u.setReprobacionVigenteConocida(Boolean.TRUE);u.setReprobacionPeriodoPrevioConocida(Boolean.TRUE);return u;} private UnidadEvaluacionCurricularV2DTO u(long id,int sem,EstadoUnidadCurricularV2 e,CausaPendienteUnidadV2 c){UnidadEvaluacionCurricularV2DTO u=new UnidadEvaluacionCurricularV2DTO();u.setIdPrograma(id);u.setClave("UD"+id);u.setTipoUd("Obligatoria");u.setSemestre(sem);u.setEstado(e);u.setCausa(c);u.setOfertada(Boolean.TRUE);u.setGrupoActivoConocido(Boolean.TRUE);u.setCupoDisponibleConocido(Boolean.TRUE);return u;}
